html:
{# ── Company ──────────────────────────────────────────────────────────────────── #}
{% set co = frappe.get_doc("Company", doc.company) %}
{% set co_addr = frappe.db.get_value("Address", doc.company_address,
    ["address_line1","address_line2","city","state","pincode"], as_dict=True)
    if doc.company_address else None %}
{% set sup_name = frappe.db.get_value("Supplier", doc.supplier, "supplier_name") or doc.supplier %}
{% set sup_addr = frappe.db.get_value("Address", doc.supplier_address,
    ["address_line1","address_line2","city","state","pincode","gstin"], as_dict=True)
    if doc.supplier_address else None %}

{# ── State codes ───────────────────────────────────────────────────────────────── #}
{% set co_state_code  = doc.company_gstin[:2]|int if doc.company_gstin and doc.company_gstin|length >= 2 else 0 %}
{% set sup_gstin      = doc.supplier_gstin or (sup_addr.gstin if sup_addr else "") or "" %}
{% set sup_state_code = sup_gstin[:2]|int if sup_gstin|length >= 2 else 0 %}
{% set is_igst        = co_state_code != sup_state_code if (co_state_code and sup_state_code) else True %}

{# ── Linked GRNs ───────────────────────────────────────────────────────────────── #}
{% set ns_grn = namespace(grn_list=[]) %}
{% for row in doc.items %}
  {% if row.purchase_receipt and row.purchase_receipt not in ns_grn.grn_list %}
    {% set _ = ns_grn.grn_list.append(row.purchase_receipt) %}
  {% endif %}
{% endfor %}

{# ── Tax summary from taxes table ─────────────────────────────────────────────── #}
{% set tax_ns = namespace(cgst=0.0, sgst=0.0, igst=0.0, other=[], total=0.0) %}
{% for tax in doc.taxes %}
  {% if tax.tax_amount %}
    {% set desc = (tax.description or tax.account_head or "").upper() %}
    {% if "CGST" in desc %}
      {% set tax_ns.cgst = tax_ns.cgst + tax.tax_amount %}
    {% elif "SGST" in desc or "UTGST" in desc %}
      {% set tax_ns.sgst = tax_ns.sgst + tax.tax_amount %}
    {% elif "IGST" in desc %}
      {% set tax_ns.igst = tax_ns.igst + tax.tax_amount %}
    {% else %}
      {% set _ = tax_ns.other.append({"label": tax.description or tax.account_head, "amount": tax.tax_amount}) %}
    {% endif %}
    {% set tax_ns.total = tax_ns.total + tax.tax_amount %}
  {% endif %}
{% endfor %}

{# ── Helpers ───────────────────────────────────────────────────────────────────── #}
{% macro fd(d) %}{% if d %}{{ frappe.utils.formatdate(d, "dd-MMM-yy") }}{% endif %}{% endmacro %}
{% macro fm(v) %}{{ frappe.utils.fmt_money(v|float, precision=2, currency=doc.currency) }}{% endmacro %}

<style>
  body   { font-family: Arial, sans-serif; font-size: 11px; color: #000; margin: 0; }
  table  { width: 100%; border-collapse: collapse; }
  td, th { padding: 4px 6px; vertical-align: top; }
  strong { font-weight: bold; }
  .box   { border: 1.5px solid #000; margin-bottom: 2px; }
  .b     { border: 1px solid #000; }
  .bb    { border-bottom: 1px solid #000; }
  .bt    { border-top: 1px solid #000; }
  .br    { border-right: 1px solid #000; }
  .ta-r  { text-align: right; }
  .ta-c  { text-align: center; }
  .lbl   { color: #555; font-size: 10px; }
  .italic{ font-style: italic; }
  .sh    { font-weight: bold; padding: 3px 6px;
           border-top: 1px solid #000; border-bottom: 1px solid #000; background: #f7f7f7; }
  .watermark { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
               display: flex; align-items: center; justify-content: center;
               pointer-events: none; z-index: 99999; overflow: hidden; }
  .watermark span { display: block; font-size: 110px; font-weight: 900;
                    color: rgba(211,47,47,.15); letter-spacing: 10px;
                    text-transform: uppercase; white-space: nowrap;
                    transform: rotate(-40deg); font-family: Arial, sans-serif;
                    border: 12px solid rgba(211,47,47,.12);
                    padding: 10px 30px; border-radius: 8px; }
</style>

{% if doc.docstatus == 2 %}
<div class="watermark"><span>CANCELLED</span></div>
{% endif %}

<div class="box">

  {# ── Title ── #}
  <div style="text-align:center; padding:5px 6px; border-bottom:1px solid #000; font-size:13px; letter-spacing:1px">
    <strong>Purchase Invoice</strong>
  </div>

  {# ── Company header (left) + PI meta grid (right) ── #}
  <table class="bb">
    <tr>
      <td class="br" style="width:55%">
        <img src="/files/letterhead.jpeg" style="width:58px; height:auto; max-height:50px; object-fit:contain; float:left; margin-right:8px; margin-bottom:4px">
        <strong>{{ doc.company | upper }}</strong><br>
        {% if co_addr %}
          {{ co_addr.address_line1 or "" }}{% if co_addr.address_line2 %}, {{ co_addr.address_line2 }}{% endif %}<br>
          {% if co_addr.city %}{{ co_addr.city }}{% endif %}{% if co_addr.pincode %} {{ co_addr.pincode }}{% endif %}<br>
        {% endif %}
        GSTIN/UIN: {{ doc.company_gstin or "—" }}<br>
        State: {{ get_state(co_state_code) if co_state_code else "—" }}, Code: {{ co_state_code or "—" }}<br>
        {% if co.phone_no %}Contact: {{ co.phone_no }}<br>{% endif %}
        {% if co.email %}E-Mail: {{ co.email }}{% endif %}
      </td>
      <td style="width:45%; padding:0; vertical-align:top">
        <table>
          <tr>
            <td class="bb br lbl" style="width:50%">PI Number</td>
            <td class="bb lbl">Posting Date</td>
          </tr>
          <tr>
            <td class="bb br"><strong>{{ doc.name }}</strong></td>
            <td class="bb"><strong>{{ fd(doc.posting_date) }}</strong></td>
          </tr>
          <tr>
            <td class="bb br lbl">Supplier Invoice No.</td>
            <td class="bb lbl">Supplier Invoice Date</td>
          </tr>
          <tr>
            <td class="bb br"><strong>{{ doc.bill_no or "—" }}</strong></td>
            <td class="bb"><strong>{{ fd(doc.bill_date) if doc.bill_date else "—" }}</strong></td>
          </tr>
          <tr>
            <td class="bb br lbl">GRN Reference(s)</td>
            <td class="bb lbl">Place of Supply</td>
          </tr>
          <tr>
            <td class="bb br">{{ ns_grn.grn_list | join(", ") if ns_grn.grn_list else "—" }}</td>
            <td class="bb">{{ doc.place_of_supply or "—" }}</td>
          </tr>
          {% if doc.lr_no %}
          <tr>
            <td class="bb br lbl">LR No.</td>
            <td class="bb lbl">LR Date</td>
          </tr>
          <tr>
            <td class="bb br">{{ doc.lr_no }}</td>
            <td class="bb">{{ fd(doc.lr_date) if doc.lr_date else "—" }}</td>
          </tr>
          {% endif %}
          <tr>
            <td class="bb br lbl">ITC Category</td>
            <td class="bb lbl">Currency</td>
          </tr>
          <tr>
            <td class="bb br">{{ doc.itc_classification or "—" }}</td>
            <td class="bb">{{ doc.currency }}</td>
          </tr>
          <tr>
            <td colspan="2" style="min-height:14px; padding:4px 6px;">&nbsp;</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  {# ── Supplier + Bill To ── #}
  <table class="bb">
    <tr>
      <td class="br" style="width:55%">
        <div class="lbl">Supplier</div>
        <strong>{{ sup_name }}</strong><br>
        {% if sup_addr %}
          {{ sup_addr.address_line1 or "" }}{% if sup_addr.address_line2 %}, {{ sup_addr.address_line2 }}{% endif %}<br>
          {{ sup_addr.city or "" }}{% if sup_addr.state %}, {{ sup_addr.state }}{% endif %}{% if sup_addr.pincode %} {{ sup_addr.pincode }}{% endif %}<br>
        {% endif %}
        GSTIN/UIN: {{ sup_gstin or "—" }}<br>
        State: {{ get_state(sup_state_code) if sup_state_code else "—" }}, Code: {{ sup_state_code or "—" }}
      </td>
      <td style="width:45%">
        <div class="lbl">Bill To</div>
        <strong>{{ doc.company }}</strong><br>
        {% if co_addr %}
          {{ co_addr.address_line1 or "" }}{% if co_addr.address_line2 %}, {{ co_addr.address_line2 }}{% endif %}<br>
          {{ co_addr.city or "" }}{% if co_addr.state %}, {{ co_addr.state }}{% endif %}{% if co_addr.pincode %} {{ co_addr.pincode }}{% endif %}<br>
        {% endif %}
        GSTIN/UIN: {{ doc.company_gstin or "—" }}<br>
        State: {{ get_state(co_state_code) if co_state_code else "—" }}, Code: {{ co_state_code or "—" }}
      </td>
    </tr>
  </table>

  {# ── Items table ── #}
  <table>
    <thead>
      <tr>
        <th class="b ta-c" style="width:4%">Sl<br>No.</th>
        <th class="b" style="width:28%">Description of Goods</th>
        <th class="b ta-c" style="width:8%">HSN/<br>SAC</th>
        <th class="b ta-c" style="width:6%">GST<br>Rate</th>
        <th class="b ta-r" style="width:7%">Qty</th>
        <th class="b ta-c" style="width:5%">UOM</th>
        <th class="b ta-r" style="width:8%">Rate</th>
        <th class="b ta-r" style="width:9%">Taxable</th>
        {% if is_igst %}
        <th class="b ta-r" style="width:8%">IGST</th>
        {% else %}
        <th class="b ta-r" style="width:7%">CGST</th>
        <th class="b ta-r" style="width:7%">SGST</th>
        {% endif %}
        <th class="b ta-r" style="width:10%">Total</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      {# Per-row GST amounts from india_compliance #}
      {% set igst_amt = (row.igst_amount or 0)|float %}
      {% set cgst_amt = (row.cgst_amount or 0)|float %}
      {% set sgst_amt = (row.sgst_amount or 0)|float %}
      {% set row_tax  = igst_amt + cgst_amt + sgst_amt %}
      {# Per-row GST rate #}
      {% set igst_r = (row.igst_rate or 0)|float %}
      {% set cgst_r = (row.cgst_rate or 0)|float %}
      {% set sgst_r = (row.sgst_rate or 0)|float %}
      {% set gst_rate_val = igst_r + cgst_r + sgst_r %}
      {# taxable from india_compliance field or fallback to row.amount #}
      {% set taxable = (row.taxable_value or row.amount or 0)|float %}
      <tr>
        <td class="b ta-c">{{ loop.index }}</td>
        <td class="b">
          <strong>{{ row.item_name or row.item_code }}</strong>
          {% if row.description and row.description != row.item_name %}
          <br><span class="italic lbl">{{ row.description | striptags | trim }}</span>
          {% endif %}
        </td>
        <td class="b ta-c">{{ row.gst_hsn_code or "" }}</td>
        <td class="b ta-c">{% if gst_rate_val %}{{ "%g" | format(gst_rate_val) }}%{% endif %}</td>
        <td class="b ta-r">{{ fm(row.qty) }}</td>
        <td class="b ta-c">{{ row.uom }}</td>
        <td class="b ta-r">{{ fm(row.rate) }}</td>
        <td class="b ta-r">{{ fm(taxable) }}</td>
        {% if is_igst %}
        <td class="b ta-r">{{ fm(igst_amt) }}</td>
        {% else %}
        <td class="b ta-r">{{ fm(cgst_amt) }}</td>
        <td class="b ta-r">{{ fm(sgst_amt) }}</td>
        {% endif %}
        <td class="b ta-r">{{ fm(taxable + row_tax) }}</td>
      </tr>
      {% endfor %}

      {# Net Total row #}
      <tr>
        {% if is_igst %}
        <td class="b" colspan="7" style="text-align:right"></td>
        <td class="b ta-r">{{ fm(doc.net_total) }}</td>
        <td class="b ta-r">{{ fm(tax_ns.igst) }}</td>
        {% else %}
        <td class="b" colspan="7" style="text-align:right"></td>
        <td class="b ta-r">{{ fm(doc.net_total) }}</td>
        <td class="b ta-r">{{ fm(tax_ns.cgst) }}</td>
        <td class="b ta-r">{{ fm(tax_ns.sgst) }}</td>
        {% endif %}
        <td class="b ta-r">{{ fm(doc.net_total + tax_ns.total) }}</td>
      </tr>

      {# Tax rows from taxes table #}
      {% for tax in doc.taxes %}
      {% if tax.tax_amount %}
      <tr class="italic">
        <td class="b" colspan="{% if is_igst %}8{% else %}9{% endif %}" style="text-align:right">
          {{ tax.description }} {{ "%g" | format(tax.rate) }} %
        </td>
        <td class="b ta-r">{{ fm(tax.tax_amount) }}</td>
      </tr>
      {% endif %}
      {% endfor %}

      {# Spacers #}
      {% for _i in range(3) %}
      <tr style="height:16px"><td class="b" colspan="{% if is_igst %}10{% else %}11{% endif %}"></td></tr>
      {% endfor %}

      {# Grand Total #}
      <tr>
        <td class="b ta-r" colspan="{% if is_igst %}9{% else %}10{% endif %}"><strong>Grand Total</strong></td>
        <td class="b ta-r"><strong>&#8377;&nbsp;{{ fm(doc.grand_total) }}</strong></td>
      </tr>
    </tbody>
  </table>

  {# ── Tax Summary ── #}
  {% if tax_ns.cgst or tax_ns.sgst or tax_ns.igst or tax_ns.other %}
  <table class="bt" style="font-size:10px">
    <thead>
      <tr>
        {% if tax_ns.cgst %}<th class="b ta-c">CGST (₹)</th>{% endif %}
        {% if tax_ns.sgst %}<th class="b ta-c">SGST / UTGST (₹)</th>{% endif %}
        {% if tax_ns.igst %}<th class="b ta-c">IGST (₹)</th>{% endif %}
        {% for o in tax_ns.other %}<th class="b ta-c">{{ o.label }}</th>{% endfor %}
        <th class="b ta-c">Total Tax (₹)</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        {% if tax_ns.cgst %}<td class="b ta-r">{{ fm(tax_ns.cgst) }}</td>{% endif %}
        {% if tax_ns.sgst %}<td class="b ta-r">{{ fm(tax_ns.sgst) }}</td>{% endif %}
        {% if tax_ns.igst %}<td class="b ta-r">{{ fm(tax_ns.igst) }}</td>{% endif %}
        {% for o in tax_ns.other %}<td class="b ta-r">{{ fm(o.amount) }}</td>{% endfor %}
        <td class="b ta-r"><strong>{{ fm(tax_ns.total) }}</strong></td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  {# ── Amount in words ── #}
  <table class="bt">
    <tr>
      <td class="br" style="width:60%">
        <strong>Amount Chargeable (in words)</strong><br>
        <strong>{{ frappe.utils.money_in_words(doc.grand_total, doc.currency) }}</strong>
      </td>
      <td class="ta-r">
        {% if doc.outstanding_amount %}
        <span class="lbl">Outstanding:</span> <strong>{{ fm(doc.outstanding_amount) }}</strong><br>
        {% endif %}
        <span class="italic">E. &amp; O.E</span>
      </td>
    </tr>
  </table>

  {# ── Remarks ── #}
  {% if doc.remarks %}
  <table class="bt">
    <tr>
      <td><strong>Remarks:</strong> {{ doc.remarks }}</td>
    </tr>
  </table>
  {% endif %}

  {# ── Signature ── #}
  <table class="bt">
    <tr>
      <td style="width:33%; text-align:center; padding:30px 6px 4px">
        <strong>Verified By</strong>
      </td>
      <td style="width:33%; text-align:center; padding:30px 6px 4px; border-left:1px solid #000">
        <strong>Accounts</strong>
      </td>
      <td style="text-align:right; padding:6px; border-left:1px solid #000">
        <div><strong>for {{ doc.company | upper }}</strong></div>
        <div style="text-align:right; margin-top:4px">
          <img src="/files/IB_Stamp.jpeg" style="height:55px; width:auto; display:inline-block">
        </div>
        <div style="margin-top:6px"><strong>Authorised Signatory</strong></div>
      </td>
    </tr>
  </table>

  <div style="text-align:center; padding:3px; border-top:1px solid #000">
    This is a Computer Generated Purchase Invoice
  </div>

</div>
